import React, { type CSSProperties, type ReactElement, type ReactNode } from 'react'
import { getReadableToneColor, getThemeColors, type ThemeMode } from 'vizmatic'

const h = React.createElement

/**
 * One drawing language for the governed support system chapters, on the default theme.
 * Green is allowed or healthy, red is held or wrong, warm needs a person, blue is facts we read,
 * and purple is generated by a model. Words and marks carry every meaning too.
 * Figures fill a 664 wide area inside a 680 canvas, so 20 px is 10 CSS px on a 343 px phone.
 * Sans type carries labels. Mono is only for identifiers and numbers.
 */
export const INNER = 664

export function kit(theme: ThemeMode = 'dark') {
    const c = getThemeColors(theme)
    const tone = (name: Parameters<typeof getReadableToneColor>[0]) => getReadableToneColor(name, c, c.bg)
    return {
        c,
        ink: c.textPrimary,
        mid: c.textSecondary,
        faint: c.textMuted,
        line: c.borderSubtle,
        go: tone('green'),
        stop: tone('critical'),
        ask: tone('warm'),
        data: tone('blue'),
        model: tone('purple'),
        read: tone('cyan'),
        onFill: theme === 'light' ? '#ffffff' : c.bg,
        sans: c.fontSans,
        mono: c.fontMono,
    }
}
export type Kit = ReturnType<typeof kit>

export function tint(color: string, amount = 0.1): string {
    const alpha = Math.round(amount * 255).toString(16).padStart(2, '0')
    return `${color}${alpha}`
}

export function figure(k: Kit, children: ReactNode, gap = 14): ReactElement {
    return h('div', { style: { display: 'flex', flexDirection: 'column', width: 680, gap, fontFamily: k.sans, color: k.ink, padding: 8, boxSizing: 'border-box' } }, children)
}

export function row(children: ReactNode, style: CSSProperties = {}): ReactElement {
    return h('div', { style: { display: 'flex', alignItems: 'center', ...style } }, children)
}

export function col(children: ReactNode, style: CSSProperties = {}): ReactElement {
    return h('div', { style: { display: 'flex', flexDirection: 'column', ...style } }, children)
}

export function space(width: number, height = 1): ReactElement {
    return h('div', { style: { display: 'flex', width, height, flexShrink: 0 } })
}

export interface LabelOptions {
    size?: number
    color?: string
    weight?: number
    mono?: boolean
    width?: number
    align?: 'left' | 'center' | 'right'
    style?: CSSProperties
}

export function label(k: Kit, text: ReactNode, o: LabelOptions = {}): ReactElement {
    const justify = o.align === 'center' ? 'center' : o.align === 'right' ? 'flex-end' : 'flex-start'
    return h('div', { style: {
        display: 'flex', justifyContent: justify, textAlign: o.align ?? 'left',
        fontSize: o.size ?? 20, fontWeight: o.weight ?? 500, lineHeight: 1.25,
        color: o.color ?? k.ink, fontFamily: o.mono ? k.mono : k.sans,
        ...(o.width ? { width: o.width } : {}), ...o.style,
    } }, text)
}

export interface BoxOptions {
    color?: string
    width?: number
    fill?: boolean
    dashed?: boolean
    style?: CSSProperties
}

/** A flat, hairline box. Fill is reserved for the marks that carry the figure's point. */
export function box(k: Kit, children: ReactNode, o: BoxOptions = {}): ReactElement {
    const color = o.color ?? k.line
    return h('div', { style: {
        display: 'flex', flexDirection: 'column', gap: 3, padding: '9px 11px', boxSizing: 'border-box',
        border: `1.5px ${o.dashed ? 'dashed' : 'solid'} ${color}`, borderRadius: 3,
        backgroundColor: o.fill ? tint(color, 0.1) : 'transparent',
        ...(o.width ? { width: o.width } : {}), ...o.style,
    } }, children)
}

export function arrow(color: string, length = 30, direction: 'right' | 'down' = 'right'): ReactElement {
    const head = 7
    const across = 16
    const width = direction === 'right' ? length : across
    const height = direction === 'right' ? across : length
    const stem = direction === 'right' ? `M1 8 H${length - head}` : `M8 1 V${length - head}`
    const tip = direction === 'right'
        ? `M${length} 8 L${length - head} 3.5 L${length - head} 12.5 Z`
        : `M8 ${length} L3.5 ${length - head} L12.5 ${length - head} Z`
    return h('svg', { width, height, viewBox: `0 0 ${width} ${height}`, style: { flexShrink: 0 } },
        h('path', { d: stem, stroke: color, strokeWidth: 2, fill: 'none' }),
        h('path', { d: tip, fill: color }))
}

export function mark(kind: 'yes' | 'no', color: string, size = 18): ReactElement {
    return h('svg', { width: size, height: size, viewBox: '0 0 16 16', style: { flexShrink: 0 } },
        h('path', {
            d: kind === 'yes' ? 'M3 8.5 L6.5 12 L13 4.5' : 'M4 4 L12 12 M12 4 L4 12',
            stroke: color, strokeWidth: 2.2, fill: 'none', strokeLinecap: 'round', strokeLinejoin: 'round',
        }))
}

/** A fork from one source into two stacked rows. Height matches the rows it joins. */
export function fork(width: number, height: number, top: number, bottom: number, colors: [string, string]): ReactElement {
    const mid = height / 2
    const [a, b] = colors
    return h('svg', { width, height, viewBox: `0 0 ${width} ${height}`, style: { flexShrink: 0 } },
        h('path', { d: `M0 ${mid} H${width / 2} V${top} H${width - 7}`, stroke: a, strokeWidth: 2, fill: 'none' }),
        h('path', { d: `M0 ${mid} H${width / 2} V${bottom} H${width - 7}`, stroke: b, strokeWidth: 2, fill: 'none' }),
        h('path', { d: `M${width} ${top} L${width - 7} ${top - 4.5} L${width - 7} ${top + 4.5} Z`, fill: a }),
        h('path', { d: `M${width} ${bottom} L${width - 7} ${bottom - 4.5} L${width - 7} ${bottom + 4.5} Z`, fill: b }))
}

/** One stem from the top that splits into a downward arrow per target. */
export function split(width: number, height: number, from: number, targets: Array<[number, string]>): ReactElement {
    const bend = height - 18
    const paths: ReactNode[] = targets.flatMap(([to, color], index) => [
        h('path', { key: `s${index}`, d: `M${from} 0 V${bend} H${to} V${height - 7}`, stroke: color, strokeWidth: 2, fill: 'none' }),
        h('path', { key: `t${index}`, d: `M${to} ${height} L${to - 4.5} ${height - 7} L${to + 4.5} ${height - 7} Z`, fill: color }),
    ])
    return h('svg', { width, height, viewBox: `0 0 ${width} ${height}`, style: { flexShrink: 0 } }, paths)
}

/** A plain SVG path, for connectors placed by the figure's own coordinates. */
export function wire(width: number, height: number, d: string, color: string, dash?: string): ReactElement {
    return h('svg', { width, height, viewBox: `0 0 ${width} ${height}` },
        h('path', { d, stroke: color, strokeWidth: 2, fill: 'none', ...(dash ? { strokeDasharray: dash } : {}) }))
}

/** A fixed area whose children are placed by coordinates with pin, hbar, and vline. */
export function area(width: number, height: number, children: ReactNode, style: CSSProperties = {}): ReactElement {
    return h('div', { style: { display: 'flex', position: 'relative', width, height, flexShrink: 0, ...style } }, children)
}

export function pin(x: number, y: number, child: ReactNode, o: { width?: number; align?: 'left' | 'center' | 'right' } = {}): ReactElement {
    const justify = o.align === 'center' ? 'center' : o.align === 'right' ? 'flex-end' : 'flex-start'
    return h('div', { style: { display: 'flex', position: 'absolute', left: x, top: y, justifyContent: justify, ...(o.width ? { width: o.width } : {}) } }, child)
}

export function hbar(x: number, y: number, width: number, height: number, color: string, child?: ReactNode, style: CSSProperties = {}): ReactElement {
    return h('div', { style: {
        display: 'flex', position: 'absolute', left: x, top: y, width, height, boxSizing: 'border-box',
        alignItems: 'center', justifyContent: 'center', backgroundColor: color, ...style,
    } }, child)
}

export function vline(x: number, y: number, height: number, color: string, dashed = false, weight = 2): ReactElement {
    return h('div', { style: { display: 'flex', position: 'absolute', left: x, top: y, width: 0, height, borderLeft: `${weight}px ${dashed ? 'dashed' : 'solid'} ${color}` } })
}

export function hline(x: number, y: number, width: number, color: string, weight = 1.5): ReactElement {
    return h('div', { style: { display: 'flex', position: 'absolute', left: x, top: y, width, height: 0, borderTop: `${weight}px solid ${color}` } })
}

export function dot(x: number, y: number, size: number, color: string): ReactElement {
    return h('div', { style: { display: 'flex', position: 'absolute', left: x - size / 2, top: y - size / 2, width: size, height: size, borderRadius: size / 2, backgroundColor: color } })
}
